import assert from 'node:assert/strict';
import {StereoReverb} from './reverb.mjs';
const sr=48000;
function impulse(wet,size,seconds=6){const r=new StereoReverb(sr);r.setParameters(wet,size);for(let i=0;i<sr/2;i++)r.process(0,0);const windows=new Float64Array(Math.ceil(seconds)),rightPeak={value:0};let peak=0;for(let i=0;i<sr*seconds;i++){r.process(i===0?1:0,0);assert.ok(Number.isFinite(r.left)&&Number.isFinite(r.right));peak=Math.max(peak,Math.abs(r.left));rightPeak.value=Math.max(rightPeak.value,Math.abs(r.right));windows[Math.floor(i/sr)]+=r.left*r.left;}return{r,windows,peak,rightPeak:rightPeak.value};}
const dry=impulse(0,.75);assert.equal(dry.peak,1);assert.equal(dry.windows[1],0);const wet=impulse(.8,.9);assert.ok(wet.windows[1]>1e-10,'real reverb tail survives source release');assert.ok(wet.windows[5]<wet.windows[1],'tail decays');assert.equal(wet.rightPeak,0,'left impulse never appears in right channel');assert.ok(wet.peak<=1);const short=impulse(1,0),long=impulse(1,1);assert.ok(long.windows[2]>short.windows[2]);wet.r.clear();for(let i=0;i<sr;i++){wet.r.process(0,0);assert.equal(wet.r.left,0);assert.equal(wet.r.right,0);}
const musical=new StereoReverb(sr);musical.setParameters(.18,.75);for(let i=0;i<sr;i++)musical.process(0,0);let musicalTail=0;for(let i=0;i<sr*1.3;i++){musical.process(i<sr*.3?.3*Math.sin(2*Math.PI*110*i/sr):0,0);if(i>=sr*.3)musicalTail+=musical.left**2;}const musicalTailRms=Math.sqrt(musicalTail/sr);assert.ok(musicalTailRms>.005,'default wet return remains measurable at musical listening levels');
console.log(JSON.stringify({ok:true,wetZeroDry:true,nonzeroTail:true,defaultMusicalTailRms:musicalTailRms,decayingTail:true,sizeChangesDecay:true,channelsIsolated:true,bounded:true,clearSilent:true},null,2));
